/**
 * Pre-generated voice clips (public/audio/<book>/manifest.json), played instead of the
 * browser's built-in speech whenever a clip exists for the exact text.
 * Generated by tools/audio/generate_book1_audio.py; provenance in docs/audio-provenance.md.
 */

export type ClipSpeed = "normal" | "listen" | "slow";

/** Clips are recorded at a gentle pace already; slower modes stretch them with pitch preserved. */
const PLAYBACK_RATE: Record<ClipSpeed, number> = { normal: 1, listen: 0.9, slow: 0.75 };
// Must match PUNCTUATION in tools/audio/generate_book1_audio.py.
const PUNCTUATION = /[\s。！？，、：；「」…!?,.:;]/g;
const HAN = /[㐀-鿿]/;
const MANIFESTS = ["audio/book1/manifest.json", "audio/feedback/manifest.json"];

export function clipKey(text: string): string {
  return text.replace(PUNCTUATION, "");
}

let clipUrls: Map<string, string> | null = null;
let loading: Promise<void> | null = null;
let current: HTMLAudioElement | null = null;
let queueToken = 0;

/** Loads the clip manifests once; safe to call repeatedly. Missing manifests just leave fewer clips. */
export function loadVoiceClips(base: string = import.meta.env.BASE_URL): Promise<void> {
  if (loading) return loading;
  loading = Promise.all(MANIFESTS.map(async (path) => {
    try {
      const response = await fetch(`${base}${path}`);
      if (!response.ok) return [] as Array<[string, string]>;
      const manifest = await response.json() as { clips?: Record<string, string> };
      const folder = path.slice(0, path.lastIndexOf("/") + 1);
      return Object.entries(manifest.clips ?? {}).map(([key, file]): [string, string] => [key, `${base}${folder}${file}`]);
    } catch {
      return [] as Array<[string, string]>;
    }
  })).then((lists) => { clipUrls = new Map(lists.flat()); });
  return loading;
}

/** The clip URLs needed to speak this text: one clip, or one per sentence when every sentence has a clip. */
export function clipsFor(text: string, urls: ReadonlyMap<string, string> | null = clipUrls): string[] | null {
  if (!urls) return null;
  const whole = urls.get(clipKey(text));
  if (whole) return [whole];
  // No lookbehind here: older iPad Safari versions fail to parse it.
  // Segments without any Chinese character are phonetic annotations (ㄋㄧˇ, nǐ) that the
  // clip already pronounces, so they are skipped instead of forcing the browser voice.
  const parts = (text.match(/[^。！？]+[。！？]?/g) ?? []).map(clipKey).filter((part) => HAN.test(part));
  if (parts.length === 0) return null;
  const sequence = parts.map((part) => urls.get(part));
  return sequence.every(Boolean) ? (sequence as string[]) : null;
}

export function stopVoiceClips(): void {
  queueToken += 1;
  current?.pause();
  current = null;
}

/** Plays the text from clips. Returns false when there is no clip, so the caller can fall back. */
export function playVoiceClips(text: string, speed: ClipSpeed): boolean {
  const sequence = clipsFor(text);
  if (!sequence) return false;
  stopVoiceClips();
  const token = queueToken;
  const playAt = (index: number) => {
    if (token !== queueToken || index >= sequence.length) return;
    const audio = new Audio(sequence[index]);
    audio.playbackRate = PLAYBACK_RATE[speed];
    audio.preservesPitch = true;
    audio.onended = () => playAt(index + 1);
    current = audio;
    void audio.play().catch(() => undefined);
  };
  playAt(0);
  return true;
}
